 142→  /** Lightweight session restore for background operations (e.g., push notification decryption)
 143→   * Only initializes the client and encryption, does NOT start sync service. */
 144→  public static restoreSessionForBackground = async (): Promise<boolean> => {
 145→    try {
 146→      // Already initialized with notification client
 147→      if (this.instance && this.notificationClient) return true;
 148→
 149→      const credentials = MatrixStorage.getLoginCredentials();
 150→      if (!credentials) return false;
 151→
 152→      await this.initialize(credentials.baseUrl);
 153→
 154→      if (!this.instance) throw new Error("Failed to initialize client");
 155→
 156→      const client: ClientInterface = this.instance;
 157→
 158→      await client.restoreSession({
 159→        accessToken: credentials.accessToken,
 160→        refreshToken: credentials.refreshToken,
 161→        userId: credentials.userId,
 162→        deviceId: credentials.deviceId,
 163→        homeserverUrl: credentials.baseUrl,
 164→        oidcData: undefined,
 165→        slidingSyncVersion: SlidingSyncVersion.Native,
 166→      });
 167→
 168→      // Wait for E2EE to be ready (required for decryption)
 169→      await client.encryption().waitForE2eeInitializationTasks();
 170→
 171→      // Create notification client for background decryption
 172→      // MultipleProcesses mode is for when main app might also be running
 173→      this.notificationClient = await client.notificationClient(
 174→        new NotificationProcessSetup.MultipleProcesses(),
 175→      );
 176→
 177→      return true;
 178→    } catch (error) {
 179→      console.error("[Background] Failed to restore session:", error);
 180→      return false;
 181→    }
 182→  };
