 296→  /** Call this after logging in to create a new client instance with the provided account.  */
 297→  public static setup = async (params: Session) => {
 298→    // Clear any existing crypto store to prevent device ID mismatches
 299→    await this.clearCryptoStore();
 300→
 301→    // Stop and clear existing instances
 302→    if (this.syncService) await this.syncService.stop();
 303→    this.instance = null;
 304→    this.syncService = null;
 305→
 306→    // Save credentials for future auto-login
 307→    MatrixStorage.saveLoginCredentials({
 308→      accessToken: params.accessToken,
 309→      refreshToken: params.refreshToken,
 310→      userId: params.userId,
 311→      deviceId: params.deviceId,
 312→      baseUrl: params.homeserverUrl,
 313→    });
 314→
 315→    // Create a fresh client instance and configure it with the session + sliding sync
 316→    await this.initialize(params.homeserverUrl);
 317→
 318→    if (!this.instance) throw new Error("Failed to initialize client");
 319→
 320→    // Use local variable to help TypeScript with type narrowing
 321→    const client: ClientInterface = this.instance;
 322→
 323→    await client.restoreSession({
 324→      accessToken: params.accessToken,
 325→      refreshToken: params.refreshToken,
 326→      userId: params.userId,
 327→      deviceId: params.deviceId,
 328→      homeserverUrl: params.homeserverUrl,
 329→      oidcData: undefined,
 330→      slidingSyncVersion: SlidingSyncVersion.Native,
 331→    });
 332→
 333→    // Verify the session is valid by making a server request
 334→    // Use the params.userId since client.userId() might not be populated yet
 335→    try {
 336→      this.profile = await client.getProfile(params.userId);
 337→    } catch (error) {
 338→      console.warn("Session validation failed:", error);
 339→      throw new Error("Session is invalid or expired");
 340→    }
 341→
 342→    this.syncService = await client.syncService().finish();
 343→
 344→    if (!this.syncService) throw new Error("Failed to initialize sync service");
 345→
 346→    await this.syncService.start();
 347→    await client.encryption().waitForE2eeInitializationTasks();
 348→
 349→    // Check if we need to bootstrap cross-signing or enable backups
 350→    try {
 351→      const encryption = client.encryption();
 352→      const backupExists = await encryption.backupExistsOnServer();
 353→      console.log("Backup exists on server:", backupExists);
 354→      console.log(
 355→        "Current verification state:",
 356→        encryption.verificationState(),
 357→      );
 358→
 359→      // If no backup exists and we're the only device, we might need to set one up
 360→      const isLastDevice = await encryption.isLastDevice();
 361→      console.log("Is last device:", isLastDevice);
 362→
 363→      // Update atoms so providers can react to the initialized service
 364→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
 365→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
 366→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
 367→    } catch (error) {
 368→      console.warn("Failed to check backup/verification status:", error);
 369→    }
 370→  };
