 550→  /** Deactivate the user's account permanently
 551→   * Warning: This is irreversible and will delete all user data */
 552→  public static deactivateAccount = async (password: string) => {
 553→    if (!this.instance) throw new Error("Client not initialized");
 554→
 555→    try {
 556→      // First request with undefined auth_data (will always fail per UIA spec)
 557→      try {
 558→        await this.instance.deactivateAccount(undefined, true);
 559→      } catch {
 560→        // Expected to fail
 561→      }
 562→
 563→      console.log(this.instance.userId(), "userId");
 564→      const userId = this.instance.userId();
 565→      if (!userId) throw new Error("User ID not found");
 566→
 567→      const authData = new AuthData.Password({
 568→        passwordDetails: AuthDataPasswordDetails.create({
 569→          identifier: userId,
 570→          password,
 571→        }),
 572→      });
 573→
 574→      // Step 4: Second request with auth data
 575→      await this.instance.deactivateAccount(authData, true);
 576→
 577→      // After successful deactivation, clean up local data
 578→      await this.logout();
 579→    } catch (error) {
 580→      console.error("Failed to deactivate account:", error);
 581→      throw error;
 582→    }
 583→  };
