15→export const RoomListProvider = () => {
16→  const client = useAtomValue(MatrixAtoms.matrixClient);
17→  const syncService = useAtomValue(MatrixAtoms.syncService);
18→  const setIsLoading = useSetAtom(MatrixAtoms.roomListLoading);
19→
20→  useEffect(() => {
21→    if (!client || !syncService) return;
22→
23→    const initRoomListService = async () => {
24→      try {
25→        // Get the room list service
26→        const roomListService = syncService.roomListService();
27→        if (!roomListService) return null;
28→
29→        // Initial room fetch
30→        await MatrixService.refreshRoomList();
31→
32→        // Set up room list service state listener
33→        const handle = roomListService.state({
34→          onUpdate: (state: RoomListServiceState) => {
35→            if (
36→              state === RoomListServiceState.SettingUp ||
37→              state === RoomListServiceState.Initial ||
38→              state === RoomListServiceState.Recovering
39→            ) {
40→              setIsLoading(true);
41→            }
42→
43→            if (state === RoomListServiceState.Running) {
44→              MatrixService.refreshRoomList().then(() => setIsLoading(false));
45→            }
46→          },
47→        });
48→
49→        return handle;
50→      } catch (error) {
51→        console.error("Failed to initialize room list service:", error);
52→        return null;
53→      } finally {
54→        setIsLoading(false);
55→      }
56→    };
57→
58→    let handle: TaskHandleInterface | null = null;
59→    initRoomListService().then((h) => {
60→      handle = h;
61→    });
62→
63→    return () => {
64→      handle?.cancel?.();
65→    };
66→  }, [client, syncService]);
67→
68→  return <></>;
69→};
