 14→export const VerifyUser: FC<NativeStackScreenProps<Routes, "verifyUser">> = ({
 15→  route,
 16→  navigation,
 17→}) => {
 18→  const { userId, flowId } = route.params;
 19→  const [loading, setLoading] = useState(false);
 20→  const [verificationStatus, setVerificationStatus] = useAtom(
 21→    MatrixAtoms.verificationStatus,
 22→  );
 23→  const [userProfile, setUserProfile] = useState<UserProfile | undefined>(
 24→    undefined,
 25→  );
 26→  const isIncomingRequest = verificationStatus === "incomingRequest";
 27→  const isWaiting = verificationStatus === "waiting" || loading;
 28→  const isCancelled = verificationStatus === "cancelled";
 29→  const isAccepted = verificationStatus === "accepted";
 30→  const isSasStarted = verificationStatus === "sasStarted";
 31→  const isEmojis = verificationStatus === "emojis";
 32→
 33→  const getTitleText = () => {
 34→    if (isIncomingRequest) return "Verification request received";
 35→    if (isSasStarted) return "SAS verification started";
 36→    if (isWaiting) return "Waiting for the other user";
 37→    if (isAccepted) return "Ready to start emoji verification";
 38→    if (isCancelled) return "Verification canceled";
 39→    return "Verify this user?";
 40→  };
 41→
 42→  const getBodyText = () => {
 43→    if (isIncomingRequest) {
 44→      return "This user wants to verify you. Accept to compare emojis and confirm your identity.";
 45→    }
 46→    if (isSasStarted) {
 47→      return "Waiting for the other device to respond with emojis...";
 48→    }
 49→    if (isWaiting) {
 50→      return "Once accepted you'll be able to continue with the verification.";
 51→    }
 52→    if (isAccepted) {
 53→      return "The other device accepted the request. Start the emoji verification.";
 54→    }
 55→    if (isCancelled) {
 56→      return "The other device canceled the verification. You can try again.";
 57→    }
 58→    return "For extra security, verify this user by comparing a set of emojis on your devices. Do this by using a trusted way to communicate.";
 59→  };
 60→
 61→  const getPrimaryAction = () => {
 62→    if (isIncomingRequest) return handleAcceptIncomingRequest;
 63→    if (isAccepted) return handleStartEmojiVerification;
 64→    return handleStartVerification;
 65→  };
 66→
 67→  const getPrimaryLabel = () => {
 68→    if (isIncomingRequest) return "Accept verification";
 69→    if (isAccepted) return "Start emoji verification";
 70→    return "Start verification";
 71→  };
 72→
 73→  const handleStartVerification = async () => {
 74→    try {
 75→      setLoading(true);
 76→      setVerificationStatus("waiting");
 77→      await MatrixService.verifyOtherUser(userId);
 78→    } catch (error) {
 79→      console.error(error);
 80→      setVerificationStatus("idle");
 81→      Toast.show({
 82→        type: "error",
 83→        text1: "Failed to start verification",
 84→      });
 85→    } finally {
 86→      setLoading(false);
 87→    }
 88→  };
 89→
 90→  const handleAcceptIncomingRequest = async () => {
 91→    if (!flowId) return;
 92→    try {
 93→      setLoading(true);
 94→      setVerificationStatus("waiting");
 95→      await MatrixService.acknowledgeVerification(userId, flowId);
 96→      await MatrixService.acceptVerificationRequest();
 97→      setVerificationStatus("accepted");
 98→    } catch (error) {
 99→      console.error(error);
100→      setVerificationStatus("idle");
101→      Toast.show({
102→        type: "error",
103→        text1: "Failed to accept verification request",
104→      });
105→    } finally {
106→      setLoading(false);
107→    }
108→  };
109→
110→  const handleStartEmojiVerification = async () => {
111→    try {
112→      setLoading(true);
113→      setVerificationStatus("sasStarted");
114→      await MatrixService.startVerification();
115→    } catch (error) {
116→      console.error(error);
117→      setVerificationStatus("accepted");
118→      Toast.show({
119→        type: "error",
120→        text1: "Failed to start emoji verification",
121→      });
122→    } finally {
123→      setLoading(false);
124→    }
125→  };
126→
127→  const handleGoBack = async () => {
128→    try {
129→      if (isIncomingRequest && flowId) {
130→        await MatrixService.acknowledgeVerification(userId, flowId);
131→        await MatrixService.cancelVerification();
132→        return;
133→      }
134→
135→      if (verificationStatus !== "idle") {
136→        await MatrixService.cancelVerification();
137→        return;
138→      }
139→    } catch (error) {
140→      console.error(error);
141→    } finally {
142→      setVerificationStatus("cancelled");
143→    }
144→  };
145→
146→  useEffect(() => {
147→    if (
148→      verificationStatus === "success" ||
149→      verificationStatus === "failed" ||
150→      verificationStatus === "cancelled"
151→    ) {
152→      setVerificationStatus("idle");
153→      navigation.goBack();
154→    }
155→  }, [verificationStatus]);
156→
157→  useEffect(() => {
158→    MatrixService.getUserProfile(userId)
159→      .then(setUserProfile)
160→      .catch(console.error);
161→  }, [userId]);
162→
163→  const renderContent = () => {
164→    if (isEmojis) return <EmojiVerification />;
165→
166→    return (
167→      <Block flex={1} justify="space-between" align="center">
168→        <Block align="center" justify="center" width="100%">
169→          <Image
170→            source={
171→              isWaiting || isSasStarted
172→                ? require("assets/images/hourglass.png")
173→                : require("assets/images/lock.png")
174→            }
175→            width={108}
176→            height={120}
177→          />
178→          <Text
179→            size={TextSize.large}
180→            margins={{ marginTop: 40, marginBottom: 8 }}
181→          >
182→            {getTitleText()}
183→          </Text>
184→          <Text color={Colors.white80} textAlign="center">
185→            {getBodyText()}
186→          </Text>
187→          {userProfile && (
188→            <Block
189→              align="center"
190→              gap={12}
191→              flexDirection="row"
192→              width="100%"
193→              background={Colors.white5}
194→              paddings={[12, 16]}
195→              margins={{ marginTop: 24 }}
196→              border={{ borderRadius: 16 }}
197→            >
198→              <UserImage
199→                avatarUrl={userProfile?.avatarUrl}
200→                displayName={userProfile?.displayName}
201→                width={64}
202→                height={64}
203→                borderRadius={999}
204→              />
205→              <Block gap={8}>
206→                <Text size={TextSize.medium} font="InstrumentSans-Bold">
207→                  {userProfile?.displayName}
208→                </Text>
209→                <Text size={TextSize.tiny} color={Colors.white50}>
210→                  {userId}
211→                </Text>
212→              </Block>
213→            </Block>
214→          )}
215→        </Block>
216→
217→        <Block paddings={[40, 0]} flexDirection="row" gap={12} width="100%">
218→          <Block flex={1}>
219→            <Button.Ghost onPress={handleGoBack}>Cancel</Button.Ghost>
220→          </Block>
221→          <Block flex={1}>
222→            {!isWaiting && !isSasStarted && (
223→              <Button.Primary
224→                width="100%"
225→                disabled={isWaiting || isSasStarted}
226→                onPress={getPrimaryAction()}
227→              >
228→                {getPrimaryLabel()}
229→              </Button.Primary>
230→            )}
231→          </Block>
232→        </Block>
233→      </Block>
234→    );
235→  };
