 11→export const EmojiVerification: FC = () => {
 12→  const [matchLoading, setMatchLoading] = useState(false);
 13→  const verificationEmojis = useAtomValue(MatrixAtoms.verificationEmojis);
 14→  const verificationSenderName = useAtomValue(
 15→    MatrixAtoms.verificationSenderName,
 16→  );
 17→
 18→  const handleEmojiMatch = async (match: boolean) => {
 19→    try {
 20→      if (!match) {
 21→        await MatrixService.declineVerification();
 22→        Toast.show({
 23→          type: "error",
 24→          text1: "Verification Declined",
 25→          text2:
