 35→      setMatchLoading(false);
 36→      Toast.show({
 37→        type: "error",
 38→        text1: "Failed to complete verification",
 39→      });
 40→    }
 41→  };
 42→
 43→  return (
 44→    <Block flex={1} justify="space-between" align="center">
 45→      <Block align="center" justify="center" flex={1}>
 46→        <Image
 47→          source={require("assets/images/lock.png")}
 48→          width={108}
 49→          height={120}
 50→        />
 51→        <Text
 52→          size={TextSize.large}
 53→          margins={{ marginTop: 40, marginBottom: 8 }}
 54→        >
 55→          Compare emojis
 56→        </Text>
 57→        <Text color={Colors.white80} textAlign="center">
 58→          {`Compare these emojis with ${verificationSenderName ?? "the other device"}. Do they match?`}
 59→        </Text>
 60→        {verificationEmojis && (
 61→          <Block
 62→            flexDirection="row"
 63→            flex={{ flexWrap: "wrap" }}
 64→            justify="center"
 65→            gap={24}
 66→            width="80%"
 67→            paddings={{ paddingVertical: 32 }}
 68→          >
 69→            {verificationEmojis.map((emoji, index) => (
 70→              <Block minHeight={100} key={index} align="center">
 71→                <Text flex={1} textAlign="center" size={TextSize.xlarge}>
 72→                  {emoji.symbol}
 73→                </Text>
 74→                <Text flex={1} textAlign="center" color={Colors.white50}>
 75→                  {emoji.description}
 76→                </Text>
 77→              </Block>
 78→            ))}
 79→          </Block>
 80→        )}
 81→      </Block>
 82→
 83→      <Block paddings={[40, 0]} flexDirection="row" gap={12} width="100%">
 84→        {matchLoading ? (
 85→          <Block flex={1} align="center">
 86→            <Loading
 87→              text="Waiting verification from other device..."
 88→              isFullScreen={false}
 89→            />
 90→          </Block>
 91→        ) : (
 92→          <>
 93→            <Block flex={1}>
 94→              <Button.Warning onPress={() => handleEmojiMatch(false)}>
 95→                They Don't Match
 96→              </Button.Warning>
 97→            </Block>
 98→            <Block flex={1}>
 99→              <Button.Primary onPress={() => handleEmojiMatch(true)}>
100→                They Match
101→              </Button.Primary>
102→            </Block>
103→          </>
104→        )}
105→      </Block>
106→    </Block>
107→  );
108→};
