```typescript
interface EncryptionInterface {
  // Backup
  backupExistsOnServer(): Promise<boolean>;
  backupState(): BackupState;
  backupStateListener(listener: BackupStateListener): TaskHandleInterface;
  enableBackups(): Promise<void>;
  waitForBackupUploadSteadyState(...): Promise<void>;
  disableRecovery(): Promise<void>;

  // Recovery
  recoveryState(): RecoveryState;
  recoveryStateListener(listener: RecoveryStateListener): TaskHandleInterface;
  enableRecovery(waitForBackupsToUpload, passphrase, progressListener): Promise<string>;
  resetRecoveryKey(): Promise<string>;
  recoverAndReset(oldRecoveryKey): Promise<string>;
  recover(recoveryKey): Promise<void>;

  // Verification
  verificationState(): VerificationState;
  verificationStateListener(listener: VerificationStateListener): TaskHandleInterface;

  // User Identity (cross-signing)
  userIdentity(userId, fallbackToServer): Promise<UserIdentityInterface | undefined>;

  // Identity reset
  resetIdentity(): Promise<IdentityResetHandleInterface | undefined>;

  // Device keys
  curve25519Key(): Promise<string | undefined>;
  ed25519Key(): Promise<string | undefined>;
  isLastDevice(): Promise<boolean>;
  hasDevicesToVerifyAgainst(): Promise<boolean>;

  // E2EE init
  waitForE2eeInitializationTasks(): Promise<void>;
}
```

